```suggestion
// At top of file, alongside other imports
import { EMessageTypesBtc, EMessageTypesEth } from '@onekeyhq/shared/types/message';

  @backgroundMethod()
  async autoSignBoundReferralCodeMessageByHDWallet({
    unsignedMessage,
    networkId,
    accountId,
  }: {
    unsignedMessage: IUnsignedMessage;
    networkId: string;
    accountId: string;
  }) {
    if (!accountUtils.isHdAccount({ accountId })) {
      return null;
    }
    const cachedPassword = await this.backgroundApi.servicePassword.getCachedPassword();
    if (!cachedPassword) {
      return null;
    }

    // Only allow ETH personal_sign or BTC ECDSA messages
    const allowed =
      unsignedMessage?.type === EMessageTypesEth.PERSONAL_SIGN ||
      unsignedMessage?.type === EMessageTypesBtc.ECDSA;
    if (!allowed) {
      return null;
    }

    try {
      const res = await this.backgroundApi.serviceSend.signMessage({
        unsignedMessage,
        networkId,
        accountId,
      });
      // Normalize to string | null
      return typeof res === 'string' ? res : res?.signature ?? null;
    } catch {
      // Fail closed on any signing error
      return null;
    }
  }
```

</details>

<!-- suggestion_end -->

