**Dont delete/reassign window.location; spy on reload with Vitest types.**

Reassigning/deleting `window.location` is brittle in JSDOM and contradicts the PR objective to use `vi.spyOn`. Also, `jest.Mock` is incorrect in a Vitest codebase. Replace with a spy and proper types; drop the unused `confirmSpy` var.


```diff
-    let originalLocation: Location;
-    let reloadSpy: jest.Mock;
-    let confirmSpy: any;
+    let reloadSpy: SpyInstance<[], void>;

-    beforeEach(() => {
-      originalLocation = window.location;
-      // @ts-expect-error - Mocking window.location for testing
-      delete window.location;
-      // @ts-expect-error - Mocking window.location for testing
-      window.location = { ...originalLocation, reload: vi.fn() };
-      reloadSpy = window.location.reload as any;
-    });
+    beforeEach(() => {
+      reloadSpy = vi.spyOn(window.location, 'reload').mockImplementation(() => {});
+    });

-    afterEach(() => {
-      vi.restoreAllMocks();
-      Object.defineProperty(window, 'location', {
-        value: originalLocation,
-        writable: true,
-      });
-    });
+    afterEach(() => {
+      reloadSpy.mockRestore();
+      vi.restoreAllMocks();
+    });
```

