if ( ! OrderUtil::custom_orders_table_usage_is_enabled() && ! empty( $args['s'] ) ) {
    $order_ids = wc_order_search( $args['s'] );

    if ( ! empty( $order_ids ) ) {
        unset( $args['s'] );
        // Merge with any existing post__in values
        if ( ! empty( $args['post__in'] ) ) {
            // Only keep IDs present in both the existing filter and the search results
            $args['post__in'] = array_intersect( $args['post__in'], $order_ids );

            // If theres no overlap, ensure the query returns no results
            if ( empty( $args['post__in'] ) ) {
                $args['post__in'] = array( 0 );
            }
        } else {
            // No prior filter: just use the search results (plus 0 as WP expects)
            $args['post__in'] = array_merge( $order_ids, array( 0 ) );
        }
    }
}
```

