	// Recursively check if all conditions in DNF are equal predicates
	var isEqualPredicate func(expr expression.Expression) bool
	isEqualPredicate = func(expr expression.Expression) bool {
		sf, ok := expr.(*expression.ScalarFunction)
		if !ok {
			// If it's not a scalar function, it's not an equal predicate
			return false
		}
		if sf.FuncName.L == ast.LogicOr {
			// For OR, all arguments must be equal predicates
			for _, arg := range sf.GetArgs() {
				if !isEqualPredicate(arg) {
					return false
				}
			}
			return true
		}
		// Check if it's an equal predicate (eq) or IN predicate (in)
