```suggestion
        # Retrieve both possible emitter options
        $csharpOptsOld = $null
        $csharpOptsNew = $null
        if ($yml["options"]) {
            if ($yml["options"]["@azure-tools/typespec-csharp"]) {
                $csharpOptsOld = $yml["options"]["@azure-tools/typespec-csharp"]
            }
            if ($yml["options"]["@azure-typespec/http-client-csharp"]) {
                $csharpOptsNew = $yml["options"]["@azure-typespec/http-client-csharp"]
            }
        }
        # Explicitly prefer the old emitter if present, otherwise use the new one
        if ($csharpOptsOld) {
            $csharpOpts = $csharpOptsOld
        } elseif ($csharpOptsNew) {
            $csharpOpts = $csharpOptsNew
        } else {
